//! Review: adversarial same-name / same-SKI pools (RFC 4158 §2.4.2, §3.5).
//!
//! Fixtures: `tests/fixtures/review/` generated by
//! `pkix-chain/tests/fixtures/review/gen.sh` (OpenSSL oracle).
//!
//! - `root.der`  — anchor `CN=Review Root`.
//! - `int.der`   — real `CN=Review Int`, signed by root.
//! - `leaf.der`  — EE signed by `int`, AKI = int's SKI.
//! - `bogus-int-{0..39}.der` — self-signed `CN=Review Int` CA certs with
//!   fresh keys but the SAME SubjectKeyIdentifier bytes as `int` (SKI is
//!   attacker-chosen; copying a public CA's SKI costs nothing).
//!
//! An attacker who can append certificates to an unordered bag (e.g. the
//! unsigned `SignedData.certificates` field of a CMS message) prepends 40
//! such certs. The only valid path is `[leaf, int]` (depth 1).

use std::cell::Cell;
use std::path::PathBuf;

use der::Decode as _;
use pkix_path::{DefaultVerifier, SignatureVerifier, TrustAnchor, ValidationPolicy};
use pkix_path_builder::{build_first_valid_path, CertPool};
use x509_cert::Certificate;

const NOW_UNIX: u64 = 1_900_000_000;

fn load(name: &str) -> Certificate {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/review")
        .join(name);
    let b = std::fs::read(&p).unwrap_or_else(|e| panic!("read {}: {e}", p.display()));
    Certificate::from_der(&b).unwrap_or_else(|e| panic!("parse {name}: {e}"))
}

fn adversarial_pool(n_bogus: usize) -> CertPool {
    let mut pool = CertPool::new();
    for i in 0..n_bogus {
        pool.add(load(&format!("bogus-int-{i}.der")));
    }
    pool.add(load("int.der"));
    pool
}

struct CountingVerifier(Cell<usize>);
impl SignatureVerifier for CountingVerifier {
    fn verify_signature(
        &self,
        algorithm: spki::AlgorithmIdentifierRef<'_>,
        issuer_spki: spki::SubjectPublicKeyInfoRef<'_>,
        message: &[u8],
        signature: &[u8],
    ) -> Result<(), pkix_path::VerificationError> {
        self.0.set(self.0.get() + 1);
        DefaultVerifier.verify_signature(algorithm, issuer_spki, message, signature)
    }
}

/// Control: without decoys the valid depth-1 path is found.
#[test]
fn review_control_no_decoys_finds_path() {
    let anchors = [TrustAnchor::from_cert(load("root.der"))];
    let policy = ValidationPolicy::new(NOW_UNIX);
    let chain = build_first_valid_path(
        &load("leaf.der"),
        &adversarial_pool(0),
        &anchors,
        &policy,
        &DefaultVerifier,
    )
    .expect("control");
    assert_eq!(chain.len(), 2);
}

/// BUG: 40 decoys placed before the real intermediate make the DFS sink its
/// entire 10 000-frame budget into the decoy subtree under the first
/// candidate and never reach the depth-1 valid path `[leaf, int]`.
/// Expected: `Ok([leaf, int])`. Observed: `Err(BudgetExceeded)`.
#[test]
fn review_decoys_hide_valid_depth1_path() {
    let anchors = [TrustAnchor::from_cert(load("root.der"))];
    let policy = ValidationPolicy::new(NOW_UNIX);
    let r = build_first_valid_path(
        &load("leaf.der"),
        &adversarial_pool(40),
        &anchors,
        &policy,
        &DefaultVerifier,
    );
    match r {
        Ok(chain) => assert_eq!(chain.len(), 2, "expected [leaf, int]"),
        Err(e) => panic!("valid depth-1 path not found with 40 decoys: {e:?}"),
    }
}

/// BUG (work amplification): number of signature verifications performed
/// for a 41-cert bag whose valid path has depth 1. A builder that checks
/// each link's signature before descending (RFC 4158 §3.5.x) needs at most
/// a few per pool cert; the current builder re-validates every yielded
/// candidate chain from the anchor down.
#[test]
fn review_decoys_signature_verification_amplification() {
    let anchors = [TrustAnchor::from_cert(load("root.der"))];
    let policy = ValidationPolicy::new(NOW_UNIX);
    let v = CountingVerifier(Cell::new(0));
    let t = std::time::Instant::now();
    let r = build_first_valid_path(
        &load("leaf.der"),
        &adversarial_pool(40),
        &anchors,
        &policy,
        &v,
    );
    let n = v.0.get();
    eprintln!(
        "result={:?} sig_verifications={n} elapsed={:?}",
        r.as_ref().map(Vec::len),
        t.elapsed()
    );
    assert!(
        n <= 4 * 41,
        "{n} signature verifications for a 41-cert pool"
    );
}

/// Byte-identical copies are considered once: 20 000 copies of one decoy
/// in front of the real intermediate must neither exhaust the
/// per-candidate budget nor hide `[leaf, int]`.
#[test]
fn review_duplicate_decoys_are_deduplicated() {
    let anchors = [TrustAnchor::from_cert(load("root.der"))];
    let policy = ValidationPolicy::new(NOW_UNIX);
    let decoy = load("bogus-int-0.der");
    let mut pool: CertPool = std::iter::repeat_n(decoy, 20_000).collect();
    pool.add(load("int.der"));
    let chain = build_first_valid_path(
        &load("leaf.der"),
        &pool,
        &anchors,
        &policy,
        &DefaultVerifier,
    )
    .expect("duplicates must not hide the valid path");
    assert_eq!(chain.len(), 2);
}

/// GitHub #11, builder half (topology-only iterator): the leaf's issuer
/// name `CN=Review Roll` matches the anchor, so `[leaf]` is yielded first;
/// the same-name key-rollover intermediate in the pool must still be
/// explored afterwards, yielding `[leaf, roll-ica]`.
#[test]
fn review_issue11_iterator_explores_same_name_pool_cert_after_anchor_match() {
    let anchors = [TrustAnchor::from_cert(load("roll-root.der"))];
    let mut pool = CertPool::new();
    pool.add(load("roll-ica.der"));
    let leaf = load("roll-leaf.der");
    let lens: Vec<usize> = pkix_path_builder::build_path_candidates(&leaf, &pool, &anchors)
        .map(|r| r.expect("no fatal error").len())
        .collect();
    assert_eq!(lens, vec![1, 2], "expected [leaf] then [leaf, roll-ica]");
}

/// GitHub #11, signature-checked search: the anchor's key did not sign the
/// leaf, so `[leaf]` is pruned and `[leaf, roll-ica]` is the only
/// candidate. Accepting it end to end also relies on the pkix-path half
/// of #11 (`validate_path` verifying a self-issued top certificate with
/// a same-name anchor's key).
#[test]
fn review_issue11_build_first_valid_path_accepts_key_rollover() {
    let anchors = [TrustAnchor::from_cert(load("roll-root.der"))];
    let policy = ValidationPolicy::new(NOW_UNIX);
    let mut pool = CertPool::new();
    pool.add(load("roll-ica.der"));
    let chain = build_first_valid_path(
        &load("roll-leaf.der"),
        &pool,
        &anchors,
        &policy,
        &DefaultVerifier,
    )
    .expect("key-rollover chain must validate");
    assert_eq!(chain.len(), 2);
}
